<?php
session_start();
require_once __DIR__ . '/database.php';
require_once __DIR__ . '/lang.php';

$ids = array_values(array_filter(array_map('intval', $_SESSION['my_orders'] ?? [])));
$orders=[];
if ($ids) {
    $ph=implode(',',array_fill(0,count($ids),'?'));
    $st=$pdo->prepare("SELECT * FROM orders WHERE id IN ($ph) ORDER BY created_at DESC");
    $st->execute($ids); $orders=$st->fetchAll();
}
function orderStatusLabel($s){ return ['yangi'=>'Yangi','tayyorlanmoqda'=>'Tayyorlanmoqda','tayyor'=>'Tayyor','yetkazilmoqda'=>'Yetkazilmoqda','yakunlangan'=>'Yakunlangan','bekor qilingan'=>'Bekor qilingan'][$s] ?? $s; }
?>
