.myorders-wrap{max-width:1050px;margin:0 auto;padding:42px 18px 70px}.myorders-head{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:26px}.myorders-head h1{font-size:34px;margin:4px 0}.myorders-head p{color:#777;margin:0}.order-list{display:grid;gap:16px}.my-order{background:var(--card,#fff);border:1px solid #e9e9e9;border-radius:20px;padding:20px;box-shadow:0 10px 30px rgba(0,0,0,.06)}.my-order-top{display:flex;justify-content:space-between;gap:15px;align-items:center}.my-order-id{font-size:18px;font-weight:900}.status{padding:8px 12px;border-radius:999px;font-size:12px;font-weight:800;background:#f2f2f2}.status.yangi{background:#fff3cd;color:#8a6400}.status.tayyorlanmoqda{background:#e9f2ff;color:#1769aa}.status.yetkazilmoqda{background:#eaf8ef;color:#168548}.status.yakunlangan{background:#eaf8ef;color:#168548}.status.bekor{background:#ffe9ea;color:#c5232c}.my-order-meta{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:16px 0}.my-order-meta div{background:#f8f8f8;border-radius:12px;padding:11px}.my-order-meta small{display:block;color:#888;font-size:11px}.my-order-meta b{display:block;margin-top:3px}.my-order-actions{display:flex;gap:9px;flex-wrap:wrap}.cancel-form{display:none;background:#fff7f7;border:1px solid #ffd4d7;border-radius:14px;padding:14px;margin-top:12px}.cancel-form textarea{width:100%;min-height:78px;resize:vertical}.empty-orders{background:#fff;border:1px dashed #d9d9d9;border-radius:20px;padding:50px;text-align:center}.empty-orders .icon{font-size:46px}.empty-orders h2{margin:10px 0 5px}.empty-orders p{color:#777}@media(max-width:700px){.myorders-head{align-items:start;flex-direction:column}.my-order-meta{grid-template-columns:1fr 1fr}}
