<?php if(!$orders): ?><div class="empty-orders"><div class="icon">🛍️</div><h2><?=htmlspecialchars(t('no_orders'))?></h2><p><?=htmlspecialchars(t('my_orders_empty_hint'))?></p><a class="btn" href="products.php"><?=htmlspecialchars(t('products'))?></a></div><?php else: ?><div class="order-list"><?php foreach($orders as $o): $st=$o['status']; $can=!in_array($st,['yakunlangan','bekor qilingan']); ?><article class="my-order" data-order-id="<?=$o['id']?>"><div class="my-order-top"><div class="my-order-id">Buyurtma <span style="font-family:monospace">FF-<?=str_pad($o['id'],6,'0',STR_PAD_LEFT)?></span></div><span class="status <?=$st==='bekor qilingan'?'bekor':$st?>"><?=htmlspecialchars(orderStatusLabel($st))?></span></div><div class="my-order-meta"><div><small>Sana</small><b><?=htmlspecialchars($o['created_at'])?></b></div><div><small>Buyurtma turi</small><b><?=!empty($o['table_number'])?'🍽️ Restoranda':'🛵 Yetkazib berish'?></b></div><div><small>Jami</small><b><?=number_format($o['total'],0,'',' ')?> so‘m</b></div></div><div class="my-order-actions"><a class="btn btn-secondary btn-sm" href="success.php?order_id=<?=$o['id']?>"><?=htmlspecialchars(t('view_receipt'))?></a><?php if($can): ?><button class="btn btn-sm" type="button" onclick="document.getElementById('cancel<?=$o['id']?>').style.display='block'"><?=htmlspecialchars(t('cancel_order'))?></button><?php endif; ?></div><?php if($can): ?><form id="cancel<?=$o['id']?>" class="cancel-form" method="post" action="cancel_order.php"><input type="hidden" name="order_id" value="<?=$o['id']?>"><strong><?=htmlspecialchars(t('cancel_reason_title'))?></strong><textarea name="reason" required placeholder="<?=htmlspecialchars(t('cancel_reason_placeholder'))?>" maxlength="500"></textarea><div style="display:flex;gap:8px;margin-top:9px"><button class="btn btn-sm" type="submit"><?=htmlspecialchars(t('confirm_cancel'))?></button><button class="btn btn-secondary btn-sm" type="button" onclick="this.closest('.cancel-form').style.display='none'"><?=htmlspecialchars(t('back'))?></button></div></form><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?></main><script src="../js/lang-switch.js"></script><script src="../js/global-i18n.js"></script><script src="../js/universal-i18n.js"></script><script>
(function(){
  const labels={uz:{yangi:'Yangi',"qabul qilingan":'Qabul qilingan',tayyorlanmoqda:'Tayyorlanmoqda',tayyor:'Tayyor',yetkazilmoqda:'Yetkazilmoqda',yakunlangan:'Yakunlangan',"bekor qilingan":'Bekor qilingan'},ru:{yangi:'Новый',"qabul qilingan":'Принят',tayyorlanmoqda:'Готовится',tayyor:'Готов',yetkazilmoqda:'Доставляется',yakunlangan:'Завершён',"bekor qilingan":'Отменён'},en:{yangi:'New',"qabul qilingan":'Accepted',tayyorlanmoqda:'Preparing',tayyor:'Ready',yetkazilmoqda:'Out for delivery',yakunlangan:'Completed',"bekor qilingan":'Cancelled'}};
  async function poll(){try{const r=await fetch('order_status_api.php?_='+Date.now(),{cache:'no-store'});const d=await r.json();if(!d.ok)return;const lang=document.documentElement.lang||'uz';(d.orders||[]).forEach(o=>{const card=document.querySelector('[data-order-id="'+o.id+'"]');if(!card)return;const badge=card.querySelector('.status');if(!badge)return;const text=(labels[lang]||labels.uz)[o.status]||o.status;badge.textContent=text;badge.className='status '+(o.status==='bekor qilingan'?'bekor':o.status);});}catch(e){}}
  if(document.querySelector('.my-order[data-order-id]')){setInterval(poll,10000);}
})();
</script></body></html>
